                    Clear Cutout
                  </button>
                )}
              </div>
              <div className="flex gap-2">
                <input
                  type="text"
                  placeholder="Paste right-side character or product PNG URL or upload below..."
                  value={activeCampaign.featureImageUrl || ''}
                  onChange={e => updateActiveCampaign({ featureImageUrl: e.target.value })}
